// Rust standard library: integer methods (i8..i128, isize, u8..u128, usize).
// They are generated by the macros int_impl! (signed) and uint_impl! (unsigned) in core/src/num/*_macros.rs, so an
// IDE lands inside the macro: the symbol is rust:core::num::int_macros::int_impl::pow. One animation covers both
// families when the method means the same thing for both.
const { group, nums } = require('./kit.cjs');
const INT = ['core', 'int_impl', /num\/int_macros\.rs$/];
const UINT = ['core', 'uint_impl', /num\/uint_macros\.rs$/];
const BOTH = [INT, UINT];
const { list, add } = group({ at: BOTH });

// ---------------------------------------------------------------- overflow-safe arithmetic

add('int/checked_add', 'checked_add', null, 'How checked_add works', 'Adds two integers; None instead of overflowing.', {
  rows: [['250 + 5', '250 + 10']], call: '250u8.checked_add(10)', note: 'a u8 holds 0 to 255', outs: ['Some(255)', 'None'],
  intro: 'checked_add returns Some(sum) when the result fits in the type, and None when it does not.',
  steps: [['250 + 5 = 255 still fits in a u8.', 0, 'o0'], ['250 + 10 = 260 is too big: None.', 1, 'o1']],
  result: 'Some(255), None', resultCap: 'Use it when overflow is a real possibility, e.g. sizes read from a file.',
}, 'format!("{:?}, {:?}", 250u8.checked_add(5), 250u8.checked_add(10))');

add('int/checked_sub', 'checked_sub', null, 'How checked_sub works', 'Subtracts; None if the result would not fit.', {
  rows: [['5 - 3', '3 - 5']], call: '3u32.checked_sub(5)', note: 'unsigned numbers cannot go below 0', outs: ['Some(2)', 'None'],
  intro: 'For unsigned types, going below zero is an overflow too.',
  steps: [['5 - 3 = 2.', 0, 'o0'], ['3 - 5 would be -2, which a u32 cannot hold: None.', 1, 'o1']],
  result: 'Some(2), None', resultCap: 'A common case: index.checked_sub(1) when the index might be 0.',
}, 'format!("{:?}, {:?}", 5u32.checked_sub(3), 3u32.checked_sub(5))');

add('int/checked_mul', 'checked_mul', null, 'How checked_mul works', 'Multiplies; None on overflow.', {
  rows: [['1000 * 1000', '100000 * 100000']], call: 'a.checked_mul(b)   // i32', note: 'i32 max ≈ 2.1 billion', outs: ['Some(1000000)', 'None'],
  intro: 'Products grow fast; checked_mul catches the moment they stop fitting.',
  steps: [['One million fits.', 0, 'o0'], ['Ten billion does not fit in an i32: None.', 1, 'o1']],
  result: 'Some(1000000), None', resultCap: 'Chain with ?: a.checked_mul(b)?.checked_add(c) inside a function returning Option.',
}, 'format!("{:?}, {:?}", 1000i32.checked_mul(1000), 100000i32.checked_mul(100000))');

add('int/checked_div', 'checked_div', null, 'How checked_div works', 'Divides; None when dividing by zero (or on overflow).', {
  rows: [['7 / 2', '7 / 0']], call: '7i32.checked_div(0)', note: 'no panic on zero', outs: ['Some(3)', 'None'],
  intro: 'Plain 7 / 0 panics. checked_div turns that into None.',
  steps: [['7 / 2 = 3 (integer division drops the remainder).', 0, 'o0'], ['Dividing by 0: None.', 1, 'o1']],
  result: 'Some(3), None', resultCap: 'For signed types, i32::MIN / -1 also overflows and gives None.',
}, 'format!("{:?}, {:?}", 7i32.checked_div(2), 7i32.checked_div(0))');

add('int/checked_rem', 'checked_rem', null, 'How checked_rem works', 'The remainder; None when dividing by zero.', {
  rows: [['17 % 5', '17 % 0']], call: '17u32.checked_rem(5)', note: 'safe %', outs: ['Some(2)', 'None'],
  intro: 'checked_rem is % without the panic.',
  steps: [['17 = 3 × 5 + 2, so the remainder is 2.', 0, 'o0'], ['% 0 has no answer: None.', 1, 'o1']],
  result: 'Some(2), None', resultCap: 'For negative numbers use rem_euclid if you want a result that is never negative.',
}, 'format!("{:?}, {:?}", 17u32.checked_rem(5), 17u32.checked_rem(0))');

add('int/checked_pow', 'checked_pow', null, 'How checked_pow works', 'Raises to a power; None on overflow.', {
  rows: [['2^10', '2^40']], call: '2i32.checked_pow(40)', note: 'powers overflow quickly', outs: ['Some(1024)', 'None'],
  intro: 'checked_pow multiplies step by step and stops if a step overflows.',
  steps: [['2^10 = 1024.', 0, 'o0'], ['2^40 is about a trillion: too big for i32.', 1, 'o1']],
  result: 'Some(1024), None', resultCap: 'The exponent is always a u32.',
}, 'format!("{:?}, {:?}", 2i32.checked_pow(10), 2i32.checked_pow(40))');

add('int/checked_neg', 'checked_neg', null, 'How checked_neg works', 'Negates; None when the negative does not fit.', {
  rows: [['5', '-128 (i8::MIN)']], call: '(-128i8).checked_neg()', note: 'i8 goes from -128 to 127', outs: ['Some(-5)', 'None'],
  intro: 'Signed types have one more negative number than positive ones, so the smallest cannot be negated.',
  steps: [['-5.', 0, 'o0'], ['+128 does not fit in an i8: None.', 1, 'o1']],
  result: 'Some(-5), None', resultCap: 'For unsigned types, only 0 can be negated.',
}, 'format!("{:?}, {:?}", 5i8.checked_neg(), (-128i8).checked_neg())');

add('int/wrapping_add', 'wrapping_add', null, 'How wrapping_add works', 'Adds and wraps around past the maximum, like a car odometer.', {
  rows: [['255 + 1', '250 + 10']], call: '255u8.wrapping_add(1)', note: 'modular arithmetic', outs: ['0', '4'],
  intro: 'wrapping_add keeps only the bits that fit: for u8, the result is (a + b) mod 256.',
  steps: [['255 + 1 = 256 wraps to 0.', 0, 'o0'], ['250 + 10 = 260 wraps to 4.', 1, 'o1']],
  result: '0, 4', resultCap: 'Used on purpose in hashes, checksums and random number generators.',
}, 'format!("{}, {}", 255u8.wrapping_add(1), 250u8.wrapping_add(10))');

add('int/wrapping_sub', 'wrapping_sub', null, 'How wrapping_sub works', 'Subtracts and wraps around below the minimum.', {
  rows: [['0 - 1', '3 - 5']], call: '0u8.wrapping_sub(1)', note: 'goes round the circle backwards', outs: ['255', '254'],
  intro: 'Below 0, a u8 wraps to the top: 0 - 1 is 255.',
  steps: [['0 - 1 wraps to 255.', 0, 'o0'], ['3 - 5 wraps to 254.', 1, 'o1']],
  result: '255, 254', resultCap: 'Handy for ring-buffer positions: (pos.wrapping_sub(1)) % len.',
}, 'format!("{}, {}", 0u8.wrapping_sub(1), 3u8.wrapping_sub(5))');

add('int/wrapping_mul', 'wrapping_mul', null, 'How wrapping_mul works', 'Multiplies and keeps only the low bits that fit.', {
  rows: [['16 * 16', '100 * 3']], call: '16u8.wrapping_mul(16)', note: 'mod 256 for u8', outs: ['0', '44'],
  intro: 'The true product is computed, then reduced modulo 2^bits.',
  steps: [['256 mod 256 = 0.', 0, 'o0'], ['300 mod 256 = 44.', 1, 'o1']],
  result: '0, 44', resultCap: 'Typical in hash functions: h = h.wrapping_mul(31).wrapping_add(c).',
}, 'format!("{}, {}", 16u8.wrapping_mul(16), 100u8.wrapping_mul(3))');

add('int/wrapping_neg', 'wrapping_neg', null, 'How wrapping_neg works', 'Negates, wrapping around: for unsigned types this gives 2^bits - x.', {
  rows: [['1u8', '-128i8']], call: '1u8.wrapping_neg()', note: 'two\'s complement', outs: ['255', '-128'],
  intro: 'Negating 1 in a u8 wraps to 255; i8::MIN stays i8::MIN.',
  steps: [['0 - 1 wraps to 255.', 0, 'o0'], ['+128 does not fit in an i8, so it wraps back to -128.', 1, 'o1']],
  result: '255, -128', resultCap: 'x & x.wrapping_neg() isolates the lowest set bit.',
}, 'format!("{}, {}", 1u8.wrapping_neg(), (-128i8).wrapping_neg())');

add('int/saturating_add', 'saturating_add', null, 'How saturating_add works', 'Adds, but stops at the maximum instead of overflowing.', {
  rows: [['200 + 100', '100 + 50']], call: '200u8.saturating_add(100)', note: 'clamped at 255', outs: ['255', '150'],
  intro: 'Like a volume knob: it goes up to the maximum and stays there.',
  steps: [['300 would overflow: the result sticks at 255.', 0, 'o0'], ['150 fits, so it is the normal sum.', 1, 'o1']],
  result: '255, 150', resultCap: 'Good for colours, health points and counters that must not wrap.',
}, 'format!("{}, {}", 200u8.saturating_add(100), 100u8.saturating_add(50))');

add('int/saturating_sub', 'saturating_sub', null, 'How saturating_sub works', 'Subtracts, but stops at the minimum (0 for unsigned).', {
  rows: [['3 - 5', '9 - 5']], call: '3u32.saturating_sub(5)', note: 'never below 0', outs: ['0', '4'],
  intro: 'saturating_sub is the safe way to subtract unsigned numbers.',
  steps: [['3 - 5 would go below 0: the result is 0.', 0, 'o0'], ['9 - 5 = 4.', 1, 'o1']],
  result: '0, 4', resultCap: 'Common: remaining = total.saturating_sub(used).',
}, 'format!("{}, {}", 3u32.saturating_sub(5), 9u32.saturating_sub(5))');

add('int/saturating_mul', 'saturating_mul', null, 'How saturating_mul works', 'Multiplies, clamping at the minimum or maximum.', {
  rows: [['100 * 2', '100 * 3']], call: '100i8.saturating_mul(3)', note: 'i8 max is 127', outs: ['127', '-128'],
  intro: 'The result is the true product, or the closest value the type can hold.',
  steps: [['200 is above 127: clamped to 127.', 0, 'o0'], ['100 * -3 = -300 is below -128: clamped to -128.', 1, 'o1']],
  result: '127, -128', resultCap: 'The sign of the true answer decides which end it sticks to.',
}, 'format!("{}, {}", 100i8.saturating_mul(2), 100i8.saturating_mul(-3))');

add('int/saturating_pow', 'saturating_pow', null, 'How saturating_pow works', 'Raises to a power, clamping at the limits.', {
  rows: [['3^4', '3^10']], call: '3u8.saturating_pow(10)', note: 'u8 max is 255', outs: ['81', '255'],
  intro: 'saturating_pow never overflows: too large becomes the maximum.',
  steps: [['3^4 = 81.', 0, 'o0'], ['3^10 = 59049: clamped to 255.', 1, 'o1']],
  result: '81, 255', resultCap: 'checked_pow tells you it overflowed; saturating_pow just caps the value.',
}, 'format!("{}, {}", 3u8.saturating_pow(4), 3u8.saturating_pow(10))');

add('int/overflowing_add', 'overflowing_add', null, 'How overflowing_add works', 'Adds and wraps, and also tells you whether it overflowed.', {
  rows: [['250 + 10', '1 + 2']], call: '250u8.overflowing_add(10)', note: '(result, overflowed?)', outs: ['(4, true)', '(3, false)'],
  intro: 'overflowing_add returns a pair: the wrapped result and a flag.',
  steps: [['260 wraps to 4, and the flag is true.', 0, 'o0'], ['3 fits: false.', 1, 'o1']],
  result: '(4, true), (3, false)', resultCap: 'Building block for big-number arithmetic: the flag is the carry.',
}, 'format!("{:?}, {:?}", 250u8.overflowing_add(10), 1u8.overflowing_add(2))');

add('int/overflowing_sub', 'overflowing_sub', null, 'How overflowing_sub works', 'Subtracts and wraps, plus a flag that says it overflowed.', {
  rows: [['0 - 1', '5 - 1']], call: '0u8.overflowing_sub(1)', note: 'the flag is the borrow', outs: ['(255, true)', '(4, false)'],
  intro: 'The result wraps like wrapping_sub; the bool reports it.',
  steps: [['0 - 1 wraps to 255: true.', 0, 'o0'], ['5 - 1 = 4: false.', 1, 'o1']],
  result: '(255, true), (4, false)', resultCap: 'The bool is called the borrow when subtracting multi-word numbers.',
}, 'format!("{:?}, {:?}", 0u8.overflowing_sub(1), 5u8.overflowing_sub(1))');

add('int/overflowing_mul', 'overflowing_mul', null, 'How overflowing_mul works', 'Multiplies and wraps, plus an overflow flag.', {
  rows: [['16 * 17', '5 * 5']], call: '16u8.overflowing_mul(17)', note: '(result, overflowed?)', outs: ['(16, true)', '(25, false)'],
  intro: '272 does not fit in a u8; 272 mod 256 is 16.',
  steps: [['272 wraps to 16: true.', 0, 'o0'], ['25 fits: false.', 1, 'o1']],
  result: '(16, true), (25, false)', resultCap: 'Use checked_mul when you only need to know if it fits.',
}, 'format!("{:?}, {:?}", 16u8.overflowing_mul(17), 5u8.overflowing_mul(5))');

// ---------------------------------------------------------------- powers, division, distance

add('int/pow', 'pow', null, 'How pow works', 'Raises an integer to a power: x multiplied by itself n times.', {
  rows: [['2', '2', '2', '2', '2']], call: '2i32.pow(5)', note: 'exponent is a u32', outs: ['32'],
  intro: 'pow(5) multiplies five 2s together.',
  steps: [['2 × 2 × 2 = 8.', [0, 1, 2]], ['× 2 × 2 = 32.', [3, 4], 'o0']],
  result: '32', resultCap: 'Overflow panics in debug builds; use checked_pow or saturating_pow when the result may be large. For floats use powi or powf.',
}, '2i32.pow(5).to_string()');

add('int/rem_euclid', 'rem_euclid', null, 'How rem_euclid works', 'A remainder that is never negative.', {
  rows: [['-7 % 3', '-7 rem_euclid 3']], call: '(-7i32).rem_euclid(3)', note: '% keeps the sign of the left side', outs: ['-1', '2'],
  intro: 'For negative numbers, % gives a negative remainder; rem_euclid always lands in 0..3.',
  steps: [['-7 % 3 = -1, because -7 = -2 × 3 - 1.', 0, 'o0'], ['rem_euclid uses -7 = -3 × 3 + 2: the answer is 2.', 1, 'o1']],
  result: '-1, 2', resultCap: 'Perfect for wrapping indexes: (i - 1).rem_euclid(len) never goes negative.',
}, 'format!("{}, {}", -7i32 % 3, (-7i32).rem_euclid(3))');

add('int/div_euclid', 'div_euclid', null, 'How div_euclid works', 'Division that rounds so the remainder is never negative.', {
  rows: [['-7 / 3', '-7 div_euclid 3']], call: '(-7i32).div_euclid(3)', note: 'pairs with rem_euclid', outs: ['-2', '-3'],
  intro: '/ rounds toward zero. div_euclid rounds down for positive divisors, matching rem_euclid.',
  steps: [['-7 / 3 = -2 (toward zero).', 0, 'o0'], ['div_euclid gives -3, since -3 × 3 + 2 = -7.', 1, 'o1']],
  result: '-2, -3', resultCap: 'Useful for grid cells: which tile is at coordinate -7 if tiles are 3 wide? Tile -3.',
}, 'format!("{}, {}", -7i32 / 3, (-7i32).div_euclid(3))');

add('int/abs_diff', 'abs_diff', null, 'How abs_diff works', 'The distance between two numbers, as an unsigned value.', {
  rows: [['3 and 10', '10 and 3']], call: '3u32.abs_diff(10)', note: 'order does not matter', outs: ['7', '7'],
  intro: 'abs_diff never underflows, even for unsigned types where 3 - 10 would panic.',
  steps: [['|3 - 10| = 7.', 0, 'o0'], ['|10 - 3| = 7.', 1, 'o1']],
  result: '7, 7', resultCap: 'For signed types it returns the unsigned type: (-5i32).abs_diff(5) is 10u32.',
}, 'format!("{}, {}", 3u32.abs_diff(10), 10u32.abs_diff(3))');

add('int/isqrt', 'isqrt', null, 'How isqrt works', 'The integer square root: the largest n with n × n ≤ x.', {
  rows: [['16', '20']], call: '20u32.isqrt()', note: 'rounds down', outs: ['4', '4'],
  intro: 'isqrt works on integers directly, without going through floats.',
  steps: [['4 × 4 = 16 exactly.', 0, 'o0'], ['4 × 4 = 16 ≤ 20 < 25 = 5 × 5: still 4.', 1, 'o1']],
  result: '4, 4', resultCap: 'Signed types panic on negative numbers; checked_isqrt returns None instead.',
}, 'format!("{}, {}", 16u32.isqrt(), 20u32.isqrt())');

add('int/ilog2', 'ilog2', null, 'How ilog2 works', 'How many times you can halve a number before it drops below 2: floor(log₂ x).', {
  rows: [['8', '1000']], call: '1000u32.ilog2()', note: 'the index of the highest 1 bit', outs: ['3', '9'],
  intro: '2^3 = 8 and 2^9 = 512 ≤ 1000 < 1024 = 2^10.',
  steps: [['8 is exactly 2^3: 3.', 0, 'o0'], ['1000 lies between 2^9 and 2^10: 9.', 1, 'o1']],
  result: '3, 9', resultCap: 'It panics for 0; checked_ilog2 returns None. ilog2 + 1 is the number of bits needed.',
}, 'format!("{}, {}", 8u32.ilog2(), 1000u32.ilog2())');

add('int/ilog10', 'ilog10', null, 'How ilog10 works', 'floor(log₁₀ x): one less than the number of decimal digits.', {
  rows: [['7', '12345']], call: '12345u32.ilog10()', note: 'digits - 1', outs: ['0', '4'],
  intro: 'ilog10 counts how many times you can divide by 10 and stay at least 1.',
  steps: [['7 has one digit: 0.', 0, 'o0'], ['12345 has five digits: 4.', 1, 'o1']],
  result: '0, 4', resultCap: 'Digit count: n.ilog10() + 1 (for n > 0).',
}, 'format!("{}, {}", 7u32.ilog10(), 12345u32.ilog10())');

add('int/ilog', 'ilog', null, 'How ilog works', 'floor(log of x in any base).', {
  rows: [['81, base 3', '100, base 3']], call: '100u32.ilog(3)', note: 'whole powers of the base', outs: ['4', '4'],
  intro: 'ilog(b) finds the largest k with b^k ≤ x.',
  steps: [['3^4 = 81 exactly: 4.', 0, 'o0'], ['81 ≤ 100 < 243 = 3^5: still 4.', 1, 'o1']],
  result: '4, 4', resultCap: 'ilog2 and ilog10 are faster versions for bases 2 and 10.',
}, 'format!("{}, {}", 81u32.ilog(3), 100u32.ilog(3))');

// ---------------------------------------------------------------- bits

add('int/count_ones', 'count_ones', null, 'How count_ones works', 'How many bits are 1.', {
  rows: [['1', '0', '1', '1']], call: '0b1011u8.count_ones()', note: '11 in binary', outs: ['3'],
  intro: 'count_ones counts the 1 bits (the "population count").',
  steps: [['Bits 1, 0, 1, 1.', [0, 1, 2, 3]], ['Three of them are 1.', [0, 2, 3], 'o0']],
  result: '3', resultCap: 'Useful with bit flags: how many options are switched on.',
}, '0b1011u8.count_ones().to_string()');

add('int/count_zeros', 'count_zeros', null, 'How count_zeros works', 'How many bits are 0, counting the full width of the type.', {
  rows: [['0000 1011']], call: '0b1011u8.count_zeros()', note: 'a u8 has 8 bits', outs: ['5'],
  intro: 'Leading zeros count too.',
  steps: [['The u8 is 0000 1011.', 0], ['Five bits are 0.', [], 'o0']],
  result: '5', resultCap: 'count_ones + count_zeros is always the bit width (8 here).',
}, '0b1011u8.count_zeros().to_string()');

add('int/leading_zeros', 'leading_zeros', null, 'How leading_zeros works', 'How many 0 bits come before the first 1.', {
  rows: [['0', '0', '0', '1', '0', '1', '1', '0']], call: '22u8.leading_zeros()', note: '22 = 0001 0110', outs: ['3'],
  intro: 'Count from the left (the most significant bit) until the first 1.',
  steps: [['Three zeros first.', [0, 1, 2], 'o0'], ['Then a 1 stops the count.', 3]],
  result: '3', resultCap: 'Bit width minus leading_zeros is the number of bits the value really needs.',
}, '22u8.leading_zeros().to_string()');

add('int/trailing_zeros', 'trailing_zeros', null, 'How trailing_zeros works', 'How many 0 bits come after the last 1: how often 2 divides the number.', {
  rows: [['0', '0', '1', '0', '1', '0', '0', '0']], call: '40u8.trailing_zeros()', note: '40 = 0010 1000', outs: ['3'],
  intro: 'Count from the right until the first 1.',
  steps: [['Three zeros at the end.', [5, 6, 7], 'o0'], ['So 40 = 5 × 2³.', 4]],
  result: '3', resultCap: 'Bit sets use it to find the lowest member quickly.',
}, '40u8.trailing_zeros().to_string()');

add('int/leading_ones', 'leading_ones', null, 'How leading_ones works', 'How many 1 bits come before the first 0.', {
  rows: [['1', '1', '1', '0', '0', '1', '0', '0']], call: '0b1110_0100u8.leading_ones()', note: 'from the left', outs: ['3'],
  intro: 'leading_ones counts the run of 1s at the top.',
  steps: [['Three 1s.', [0, 1, 2], 'o0'], ['A 0 ends the run.', 3]],
  result: '3', resultCap: 'In UTF-8, leading_ones of the first byte tells how many bytes the character uses.',
}, '0b1110_0100u8.leading_ones().to_string()');

add('int/trailing_ones', 'trailing_ones', null, 'How trailing_ones works', 'How many 1 bits there are at the right end.', {
  rows: [['0', '0', '0', '0', '0', '1', '1', '1']], call: '7u8.trailing_ones()', note: '7 = 0000 0111', outs: ['3'],
  intro: 'trailing_ones counts the run of 1s at the bottom.',
  steps: [['Three 1s at the end.', [5, 6, 7], 'o0'], ['Then a 0.', 4]],
  result: '3', resultCap: 'x.trailing_ones() is the index of the lowest 0 bit.',
}, '7u8.trailing_ones().to_string()');

add('int/rotate_left', 'rotate_left', null, 'How rotate_left works', 'Shifts bits left; bits that fall off the top come back at the bottom.', {
  rows: [['1', '0', '0', '0', '0', '0', '0', '1']], call: '0b1000_0001u8.rotate_left(1)', note: 'nothing is lost', outs: ['3'],
  intro: 'Unlike <<, rotation keeps every bit.',
  steps: [['The top 1 leaves on the left...', 0, 'x'], ['...and re-enters on the right: 0000 0011 = 3.', [0, 7], 'o0']],
  result: '3', resultCap: 'rotate_right goes the other way. Common in hash functions and ciphers.',
}, '0b1000_0001u8.rotate_left(1).to_string()');

add('int/rotate_right', 'rotate_right', null, 'How rotate_right works', 'Shifts bits right; bits that fall off the bottom come back at the top.', {
  rows: [['0', '0', '0', '0', '0', '0', '0', '1']], call: '1u8.rotate_right(1)', note: '0000 0001', outs: ['128'],
  intro: 'The lowest bit wraps around to the highest position.',
  steps: [['The 1 leaves on the right...', 7, 'x'], ['...and comes back on the left: 1000 0000 = 128.', 0, 'o0']],
  result: '128', resultCap: 'x.rotate_right(n) == x.rotate_left(bits - n).',
}, '1u8.rotate_right(1).to_string()');

add('int/reverse_bits', 'reverse_bits', null, 'How reverse_bits works', 'Mirrors the bits: the first becomes the last.', {
  rows: [['0', '0', '0', '0', '0', '1', '1', '0']], call: '6u8.reverse_bits()', note: '0000 0110', outs: ['96'],
  intro: 'Every bit moves to the mirrored position.',
  steps: [['0000 0110 read backwards is 0110 0000.', [5, 6]], ['That is 96.', [], 'o0']],
  result: '96', resultCap: 'Used in FFT and some CRC algorithms.',
}, '6u8.reverse_bits().to_string()');

add('int/swap_bytes', 'swap_bytes', null, 'How swap_bytes works', 'Reverses the order of the bytes.', {
  rows: [['12', '34']], call: '0x1234u16.swap_bytes()', note: 'two bytes, hex', outs: ['0x3412'],
  intro: 'swap_bytes converts between big-endian and little-endian layouts.',
  steps: [['The bytes are 12 and 34.', [0, 1]], ['Swapped: 34 12.', [], 'o0']],
  result: '0x3412', resultCap: 'Usually you want to_be_bytes / from_le_bytes instead, which say what they mean.',
}, 'format!("{:#x}", 0x1234u16.swap_bytes())');

add('int/to_be_bytes', 'to_be_bytes', null, 'How to_be_bytes works', 'The bytes of the number, most significant first (big-endian).', {
  rows: [['0x12345678']], call: '0x12345678u32.to_be_bytes()', note: 'network byte order', outs: ['0x12', '0x34', '0x56', '0x78'],
  intro: 'Big-endian puts the "big end" first, the way we write numbers.',
  steps: [['The highest byte, 0x12, comes first.', 0, 'o0'], ['Then 0x34, 0x56 and 0x78.', 0, 'o1,2,3']],
  result: '[18, 52, 86, 120]', resultCap: 'Network protocols and many file formats use big-endian.',
}, 'd(0x12345678u32.to_be_bytes())');

add('int/to_le_bytes', 'to_le_bytes', null, 'How to_le_bytes works', 'The bytes of the number, least significant first (little-endian).', {
  rows: [['0x12345678']], call: '0x12345678u32.to_le_bytes()', note: 'x86 and ARM order', outs: ['0x78', '0x56', '0x34', '0x12'],
  intro: 'Little-endian puts the lowest byte first.',
  steps: [['The lowest byte, 0x78, comes first.', 0, 'o0'], ['Then 0x56, 0x34 and 0x12.', 0, 'o1,2,3']],
  result: '[120, 86, 52, 18]', resultCap: 'Most CPUs store numbers this way; formats like PNG use big-endian.',
}, 'd(0x12345678u32.to_le_bytes())');

add('int/from_be_bytes', 'from_be_bytes', null, 'How from_be_bytes works', 'Builds a number from bytes, most significant first.', {
  rows: [['0x01', '0x00']], call: 'u16::from_be_bytes([1, 0])', note: 'reading a file header', outs: ['256'],
  intro: 'The first byte is the high part: 1 × 256 + 0.',
  steps: [['0x01 is the high byte: 256.', 0], ['0x00 is the low byte: + 0.', 1, 'o0']],
  result: '256', resultCap: 'The array length must match the type: 2 bytes for u16, 4 for u32.',
}, 'u16::from_be_bytes([1, 0]).to_string()');

add('int/from_le_bytes', 'from_le_bytes', null, 'How from_le_bytes works', 'Builds a number from bytes, least significant first.', {
  rows: [['0x01', '0x00']], call: 'u16::from_le_bytes([1, 0])', note: 'same bytes, other order', outs: ['1'],
  intro: 'The first byte is the low part: 1 + 0 × 256.',
  steps: [['0x01 is the low byte: 1.', 0], ['0x00 is the high byte: + 0.', 1, 'o0']],
  result: '1', resultCap: 'The same two bytes mean 256 in big-endian: always know which order a format uses.',
}, 'u16::from_le_bytes([1, 0]).to_string()');

// ---------------------------------------------------------------- signed only

add('int/abs', 'abs', INT, 'How abs works', 'The absolute value: the number without its sign.', {
  rows: [['-7', '7']], call: '(-7i32).abs()', note: 'distance from 0', outs: ['7', '7'],
  intro: 'abs turns negative numbers positive and leaves positive ones alone.',
  steps: [['-7 becomes 7.', 0, 'o0'], ['7 stays 7.', 1, 'o1']],
  result: '7, 7', resultCap: 'i32::MIN.abs() overflows; unsigned_abs() or checked_abs() avoid that. Write (-7i32).abs(): -7i32.abs() means -(7.abs()).',
}, 'format!("{}, {}", (-7i32).abs(), 7i32.abs())');

add('int/signum', 'signum', INT, 'How signum works', '-1, 0 or 1, depending on the sign.', {
  rows: [['-42', '0', '9']], call: 'x.signum()', note: 'just the sign', outs: ['-1', '0', '1'],
  intro: 'signum reduces a number to its direction.',
  steps: [['Negative: -1.', 0, 'o0'], ['Zero: 0.', 1, 'o1'], ['Positive: 1.', 2, 'o2']],
  result: '-1, 0, 1', resultCap: 'For comparisons, a.cmp(&b) gives an Ordering, which is usually clearer.',
}, 'format!("{}, {}, {}", (-42i32).signum(), 0i32.signum(), 9i32.signum())');

add('int/is_negative', 'is_negative', INT, 'How is_negative works', 'true for numbers below zero.', {
  rows: [['-3', '0', '5']], call: 'x.is_negative()', note: '0 is not negative', outs: ['true', 'false', 'false'],
  intro: 'is_negative is the same as x < 0.',
  steps: [['-3: true.', 0, 'o0'], ['0: false.', 1, 'o1'], ['5: false.', 2, 'o2']],
  result: 'true, false, false', resultCap: 'is_positive is the counterpart; 0 is neither.',
}, 'format!("{}, {}, {}", (-3i32).is_negative(), 0i32.is_negative(), 5i32.is_negative())');

add('int/is_positive', 'is_positive', INT, 'How is_positive works', 'true for numbers above zero.', {
  rows: [['-3', '0', '5']], call: 'x.is_positive()', note: '0 is not positive', outs: ['false', 'false', 'true'],
  intro: 'is_positive is the same as x > 0.',
  steps: [['-3: false.', 0, 'o0'], ['0: false.', 1, 'o1'], ['5: true.', 2, 'o2']],
  result: 'false, false, true', resultCap: 'Only signed integer types have it.',
}, 'format!("{}, {}, {}", (-3i32).is_positive(), 0i32.is_positive(), 5i32.is_positive())');

add('int/unsigned_abs', 'unsigned_abs', INT, 'How unsigned_abs works', 'The absolute value as the unsigned type, so it can never overflow.', {
  rows: [['-5i8', '-128i8 (MIN)']], call: '(-128i8).unsigned_abs()', note: 'i8 → u8', outs: ['5', '128'],
  intro: 'abs() of i8::MIN would be 128, which an i8 cannot hold. A u8 can.',
  steps: [['-5 → 5u8.', 0, 'o0'], ['-128 → 128u8: no overflow.', 1, 'o1']],
  result: '5, 128', resultCap: 'Ideal when you need the size of a value no matter its sign.',
}, 'format!("{}, {}", (-5i8).unsigned_abs(), (-128i8).unsigned_abs())');

add('int/checked_abs', 'checked_abs', INT, 'How checked_abs works', 'abs, but None for the one value that has no positive twin.', {
  rows: [['-5', 'i32::MIN']], call: 'i32::MIN.checked_abs()', note: 'the only overflow case', outs: ['Some(5)', 'None'],
  intro: 'For every value except MIN, the absolute value fits.',
  steps: [['-5 → Some(5).', 0, 'o0'], ['MIN has no positive counterpart: None.', 1, 'o1']],
  result: 'Some(5), None', resultCap: 'wrapping_abs returns MIN unchanged; saturating_abs returns MAX.',
}, 'format!("{:?}, {:?}", (-5i32).checked_abs(), i32::MIN.checked_abs())');

add('int/checked_add_unsigned', 'checked_add_unsigned', INT, 'How checked_add_unsigned works', 'Adds an unsigned amount to a signed number; None on overflow.', {
  rows: [['-10 + 3u32', 'i32::MAX + 1u32']], call: '(-10i32).checked_add_unsigned(3)', note: 'mixing signed and unsigned', outs: ['Some(-7)', 'None'],
  intro: 'No cast needed: the unsigned amount is added directly.',
  steps: [['-10 + 3 = -7.', 0, 'o0'], ['MAX + 1 does not fit: None.', 1, 'o1']],
  result: 'Some(-7), None', resultCap: 'The unsigned twin is checked_add_signed, for adding a possibly negative offset to a usize.',
}, 'format!("{:?}, {:?}", (-10i32).checked_add_unsigned(3), i32::MAX.checked_add_unsigned(1))');

// ---------------------------------------------------------------- unsigned only

add('uint/is_power_of_two', 'is_power_of_two', UINT, 'How is_power_of_two works', 'true if the number is 1, 2, 4, 8, 16, …', {
  rows: [['64', '96']], call: 'x.is_power_of_two()', note: 'exactly one 1 bit', outs: ['true', 'false'],
  intro: 'A power of two has exactly one bit set.',
  steps: [['64 = 0100 0000: one bit, true.', 0, 'o0'], ['96 = 0110 0000: two bits, false.', 1, 'o1']],
  result: 'true, false', resultCap: '0 is not a power of two. Only unsigned types have this method.',
}, 'format!("{}, {}", 64u32.is_power_of_two(), 96u32.is_power_of_two())');

add('uint/next_power_of_two', 'next_power_of_two', UINT, 'How next_power_of_two works', 'The smallest power of two that is at least the number.', {
  rows: [['5', '16', '17']], call: 'x.next_power_of_two()', note: 'round up to 2^k', outs: ['8', '16', '32'],
  intro: 'Numbers that already are powers of two stay the same.',
  steps: [['5 rounds up to 8.', 0, 'o0'], ['16 already is one.', 1, 'o1'], ['17 rounds up to 32.', 2, 'o2']],
  result: '8, 16, 32', resultCap: 'Buffers and hash tables often size themselves this way. checked_next_power_of_two returns None on overflow.',
}, 'format!("{}, {}, {}", 5u32.next_power_of_two(), 16u32.next_power_of_two(), 17u32.next_power_of_two())');

add('uint/div_ceil', 'div_ceil', UINT, 'How div_ceil works', 'Division that rounds up.', {
  rows: [['10 / 3', '9 / 3']], call: '10u32.div_ceil(3)', note: 'how many boxes of 3 for 10 items?', outs: ['4', '3'],
  intro: 'Normal / rounds down; div_ceil rounds any remainder up.',
  steps: [['10 / 3 = 3.33…: 4 boxes are needed.', 0, 'o0'], ['9 / 3 is exact: 3.', 1, 'o1']],
  result: '4, 3', resultCap: 'Page counts: total_items.div_ceil(per_page).',
}, 'format!("{}, {}", 10u32.div_ceil(3), 9u32.div_ceil(3))');

add('uint/next_multiple_of', 'next_multiple_of', UINT, 'How next_multiple_of works', 'Rounds up to the next multiple of a number.', {
  rows: [['13 → ×8', '16 → ×8']], call: '13u32.next_multiple_of(8)', note: 'alignment', outs: ['16', '16'],
  intro: 'The smallest multiple of 8 that is at least the number.',
  steps: [['13 rounds up to 16.', 0, 'o0'], ['16 already is a multiple.', 1, 'o1']],
  result: '16, 16', resultCap: 'Typical for aligning sizes and offsets in memory or in files.',
}, 'format!("{}, {}", 13u32.next_multiple_of(8), 16u32.next_multiple_of(8))');

add('uint/is_multiple_of', 'is_multiple_of', UINT, 'How is_multiple_of works', 'true if the number divides evenly.', {
  rows: [['12, 4', '12, 5', '0, 0']], call: '12u32.is_multiple_of(4)', note: 'like x % n == 0', outs: ['true', 'false', 'true'],
  intro: 'is_multiple_of reads better than % and does not panic for 0.',
  steps: [['12 = 3 × 4: true.', 0, 'o0'], ['12 is not a multiple of 5: false.', 1, 'o1'], ['0 is a multiple of everything, even 0.', 2, 'o2']],
  result: 'true, false, true', resultCap: 'x % 0 would panic; is_multiple_of(0) is only true for x == 0.',
}, 'format!("{}, {}, {}", 12u32.is_multiple_of(4), 12u32.is_multiple_of(5), 0u32.is_multiple_of(0))');

add('uint/checked_add_signed', 'checked_add_signed', UINT, 'How checked_add_signed works', 'Adds a possibly negative offset to an unsigned number; None if it leaves the range.', {
  rows: [['5 + (-2)', '1 + (-2)']], call: 'index.checked_add_signed(step)', note: 'moving through a list', outs: ['Some(3)', 'None'],
  intro: 'Great for moving an index by -1 or +1 without casts.',
  steps: [['5 - 2 = 3.', 0, 'o0'], ['1 - 2 would be below 0: None.', 1, 'o1']],
  result: 'Some(3), None', resultCap: 'saturating_add_signed and wrapping_add_signed are the other flavours.',
}, 'format!("{:?}, {:?}", 5usize.checked_add_signed(-2), 1usize.checked_add_signed(-2))');

